head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > captionAuto]<br/>GridView 컴포넌트의 caption 값을 Header 값의 조합으로 자동 생성할지 설정합니다.",
    "validation" : [
        "true 설정 시 Header 값을 조합하여 caption 값을 자동 생성합니다.",
        "true 설정 시 captionTitle 속성이 설정되어 있으면 caption 값 앞부분에 captionTitle 속성값이 추가됩니다.",
        "true 설정 시 자동 생성되는 caption 값은 '{captionTitle}은(는) {Header 값 조합} 을(를) 나타낸 표.' 가 됩니다.",
        "false(기본값) 설정 시 디자인 시 정의된 GridViewCaption 에 맞게 caption 값이 생성됩니다.",
        "미설정 시 기본값 false 로 동작합니다.",
        "setCaption() 메소드를 사용하여 caption 값 전체를 동적으로 설정할 수 있습니다.",
        "숨김 처리된 Column 의 Header 값은 caption 값으로 포함되지 않습니다.",
        "accessibility=true 이면 shortcut 안내 문구가 caption 에 추가됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // captionAuto 동작 조건 라벨 생성
    $c.gcm.createLabel('label="Header 값: 사번 / 이름 / 부서 / 직급 (Column2 은 hidden=true 로 숨김 처리)"', '', 'label1');
    $c.gcm.createLabel('label="captionTitle: 사원 정보 / accessibility: con_accessibility 옵션 선택값 적용"', '', 'label2');

    // dataList 생성
    $c.gcm.createBasicDataList('', '', 'dlt_bind');

    // 조건 설정 - captionAuto / captionTitle / accessibility
    let captionAutoText = con_captionAuto.getText();
    let captionTitleText = con_captionTitle.getText();
    let accessibilityText = con_accessibility.getText();

    // target 생성 (Header 값을 의미있는 한글 라벨로 구성한 custom gridView)
    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    let captionAutoAttr   = captionAutoText   === '' ? '' : 'captionAuto="'   + captionAutoText   + '" ';
    let captionTitleAttr  = captionTitleText  === '' ? '' : 'captionTitle="'  + captionTitleText  + '" ';
    let accessibilityAttr = accessibilityText === '' ? '' : 'accessibility="' + accessibilityText + '" ';

    strTarget += '<w2:gridView ' + strNameSpace + ' ' + captionAutoAttr + captionTitleAttr + accessibilityAttr + 'dataList="data:dlt_bind" checkAllType="false" id="" style="width:600px;height:200px;">';
    strTarget += '<w2:caption style="" id="caption1" value="디자인 시 정의된 GridViewCaption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="120" inputType="text" id="column1" value="사번"></w2:column>';
    strTarget += '<w2:column width="120" inputType="text" id="column2" hidden="true" value="이름"></w2:column>';
    strTarget += '<w2:column width="120" inputType="text" id="column3" value="부서"></w2:column>';
    strTarget += '<w2:column width="120" inputType="text" id="column4" value="직급"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="120" inputType="text" id="col1" value=""></w2:column>';
    strTarget += '<w2:column width="120" inputType="text" hidden="true" id="col2" value=""></w2:column>';
    strTarget += '<w2:column width="120" inputType="text" id="col3" value=""></w2:column>';
    strTarget += '<w2:column width="120" inputType="text" id="col4" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

}



// 공통: caption 값 출력
scwin.getCaptionText = function () {
    let captionEl = document.querySelector("#" + target1.id + "_body_table caption");
    return captionEl ? captionEl.innerHTML : "";
}



// 1) 현재 caption 확인
scwin.btn_getCaption_onclick = function () {
    wf_body_bottom.getObj("scwin").setReturnValue("caption : " + scwin.getCaptionText());
}

// 2) setCaption() 으로 caption 값 전체 동적 설정
scwin.btn_setCaption_onclick = function () {
    target1.setCaption("동적으로 설정한 caption 값 입니다.");
    wf_body_bottom.getObj("scwin").setReturnValue("caption : " + scwin.getCaptionText());
}

// 3) Column1(이름) 숨김 해제 후 caption 재확인 (captionAuto=true 인 경우 숨김 제외 동작 확인)
scwin.btn_showHiddenCol_onclick = function () {
    target1.setColumnVisible(1, true);
    // captionAuto 자동 caption 은 컴포넌트 초기 생성 시 1회 적용되므로 숨김 해제 후 setCaptionAuto() 호출로 재생성
    if (target1.options.captionAuto === true || target1.options.captionAuto === 'true') {
        target1.setCaptionAuto();
    }
    wf_body_bottom.getObj("scwin").setReturnValue("caption : " + scwin.getCaptionText());
}
